-- V012__create_audit_triggers.sql — 自動稽核 Trigger（SCHEMA §6.2, §8.1 V012）
--   platform.audit_trigger_fn() + 套用於 accounts / wallets / entitlements
-- 依賴 V002(accounts) / V003(wallets) / V005(entitlements) / V010(platform.audit_log)。
-- Generated by gencode[foundation-migrations].
--
-- 註（SCHEMA §6.2）：wallet_ledger / records 為 append-only，本身即審計記錄，
--   不另套稽核 trigger（避免重複）。
-- 版本斷點說明：V011 保留給 foundation-seed（catalog / error_code 種子 DML）；
--   本 sub-step（foundation-migrations）只產 DDL，不含 DML（template Review #11 / anti-fake）。
-- ════════════════════════════════════════════════════════════════════════════

-- ── 通用稽核 trigger function（SCHEMA §6.2）──────────────────────────────────────
CREATE OR REPLACE FUNCTION platform.audit_trigger_fn()
RETURNS TRIGGER AS $$
DECLARE
  old_data JSONB; new_data JSONB;
BEGIN
  IF TG_OP = 'DELETE' THEN old_data := to_jsonb(OLD); new_data := NULL;
  ELSIF TG_OP = 'INSERT' THEN old_data := NULL; new_data := to_jsonb(NEW);
  ELSE old_data := to_jsonb(OLD); new_data := to_jsonb(NEW);
  END IF;

  -- record_id 由列的 JSONB 取其識別鍵：優先 id（accounts/entitlements），
  -- 無 id 欄者退 account_id（wallet.wallets PK 為 account_id，無 id 欄）。
  -- 以 JSONB 取值避免對無該欄位的 composite record 直接取 NEW.id（會 raise
  -- 'record "new" has no field "id"'，SCHEMA §3.2.1 wallets PK=account_id）。
  INSERT INTO platform.audit_log(bc_name, table_name, record_id, operation, old_values, new_values, actor_account_id)
  VALUES (TG_ARGV[0], TG_TABLE_NAME,
          COALESCE(new_data->>'id', old_data->>'id', new_data->>'account_id', old_data->>'account_id'),
          TG_OP, old_data, new_data,
          current_setting('app.current_account_id', true)::BIGINT);
  RETURN COALESCE(NEW, OLD);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMENT ON FUNCTION platform.audit_trigger_fn() IS '高業務重要性表自動稽核（寫入 platform.audit_log，SCHEMA §6.2）';

-- ── 套用於高業務重要性表（SCHEMA §6.2）──────────────────────────────────────────
CREATE TRIGGER trg_accounts_audit
  AFTER INSERT OR UPDATE OR DELETE ON member.accounts
  FOR EACH ROW EXECUTE FUNCTION platform.audit_trigger_fn('member');

CREATE TRIGGER trg_wallets_audit
  AFTER INSERT OR UPDATE OR DELETE ON wallet.wallets
  FOR EACH ROW EXECUTE FUNCTION platform.audit_trigger_fn('wallet');

CREATE TRIGGER trg_entitlements_audit
  AFTER INSERT OR UPDATE OR DELETE ON entitlement.entitlements
  FOR EACH ROW EXECUTE FUNCTION platform.audit_trigger_fn('entitlement');

